mapper.select:
SELECT id, module_name, operation_type, target_type, target_id, operator_id, operator_name,
       before_data, after_data, remark, create_time
FROM dms_operation_log


        AND module_name = #{moduleName}


        AND target_type = #{targetType}


        AND target_id = #{targetId}


ORDER BY create_time DESC, id DESC

SELECT id
FROM dms_operation_log
WHERE create_time < #{cutoff}
ORDER BY id
LIMIT #{limit}

mapper.delete:
DELETE FROM dms_operation_log
WHERE id IN
#{id}
